struct map_node {
  int color;
  map_node* parent;
  map_node* left;
  map_node* right;
  struct value_type { int first; entity_pool* second; } value;
};

struct map_iterator {
  map_node* node;
  map_iterator(map_node* n) : node(n) {}
  bool operator!=(const map_iterator& x) const { return node != x.node; }
  map_iterator& operator++() {
    if (node->right) {
      node = node->right;
      while (node->left) node = node->left;
    } else {
      map_node* y = node->parent;
      while (node == y->right) { node = y; y = y->parent; }
      if (node->right != y) node = y;
    }
    return *this;
  }
  const map_node::value_type& operator*() const { return node->value; }
};

